import {ApiClient, CONFIG} from '@smarttestpro/smart-common';

const SmartTestClient = ApiClient.getInstance('smart-test');
SmartTestClient.setEndpoint(CONFIG.API.API_ENDPOINT);

export const getMyStudyBook = () => {
  return SmartTestClient.api.get('/studybook/mystudybook');
};

export const getMyExam = (username: string) => {
  return SmartTestClient.api.get(`/dethihocsinh/mathisinh/${username}`);
};

export const getStudyBookTableContent = (studyBookId: string) => {
  return SmartTestClient.api.get(
    `/studybook/get-mon-hoc-by-code/${studyBookId}`,
  );
};
